start = s.index('def brute(job, out):')
end = s.index('def feasible(job, out):')
new = '''def brute(job, out):
    """Independently compute the optimum with networkx."""
    import ipaddress
    active = {row['id']: row['active'] for row in out['active_requests']}
    leases = {l['id']: l for l in job['leases']}
    rnodes = {n['id']: n for n in job['request_quotas']}
    onodes = {n['id']: n for n in job['offer_quotas']}
    requests = {r['id']: r for r in job['requests']}
    G = nx.DiGraph()
    G.add_node('S'); G.add_node('T')
    edges = []
    for o in job['offers']:
        for rid in o['requests']:
            r = requests[rid]
            if not active.get(rid):
                continue
            if r['service'] != o['service']:
                continue
            if not (r['at'] <= o['time'] < leases[r['lease']]['end']):
                continue
            if ipaddress.IPv6Address(r['target']) not in ipaddress.IPv6Network(o['prefix']):
                continue
            edges.append((rid, o['id'], o['cost']))
    if not edges:
        return 0, 0
    used_requests = {e[0] for e in edges}
    used_offers = {e[1] for e in edges}
    for rid in used_requests:
        G.add_edge('S', 'R' + rid, capacity=1, weight=0)
        g = requests[rid]['group']
        G.add_edge('RQ' + g, 'R' + rid, capacity=1, weight=0)
    for node in rnodes:
        parent = rnodes[node]['parent']
        if parent is None:
            G.add_edge('S', 'RQ' + node, capacity=rnodes[node]['capacity'], weight=0)
        else:
            G.add_edge('RQ' + parent, 'RQ' + node, capacity=rnodes[node]['capacity'], weight=0)
    for oid in used_offers:
        o = {x['id']: x for x in job['offers']}[oid]
        G.add_edge('O' + oid, 'OQ' + o['group'], capacity=o['capacity'], weight=0)
    for node in onodes:
        parent = onodes[node]['parent']
        if parent is None:
            G.add_edge('OQ' + node, 'T', capacity=onodes[node]['capacity'], weight=0)
        else:
            G.add_edge('OQ' + node, 'OQ' + parent, capacity=onodes[node]['capacity'], weight=0)
    for rid, oid, cost in edges:
        G.add_edge('R' + rid, 'O' + oid, capacity=1, weight=cost)
    value = nx.maximum_flow_value(G, 'S', 'T')
    if value == 0:
        return 0, 0
    H = nx.DiGraph(G)
    H.add_node('S', demand=-value); H.add_node('T', demand=value)
    cost, _ = nx.network_simplex(H)
    return value, cost


'''
s = s[:start] + new + s[end:]
open(p,'w').write(s)
